#!/usr/bin/env bash
# test-staging-format-jq.sh -- the jq twin of the staging-block grammar (lib/reflect/staging-format.jq)
# and the shlex splitter (lib/reflect/shlex-split.sh) reproduce their Python originals on the
# goldens in tests/fixtures/staging-format-jq/, generated by its gen-expected.sh from
# lib/reflect/staging-format.py and the stdlib shlex. The twin exists so the bash hooks need no
# Python; this test is what keeps the two grammars from drifting.
set -uo pipefail
KIT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
FIX="$KIT_DIR/tests/fixtures/staging-format-jq"
LIB="$KIT_DIR/lib/reflect"
pass=0; fail=0
check() { # <what> <mismatch-lines>
  if [ -z "$2" ]; then pass=$((pass + 1)); echo "  PASS $1"; else fail=$((fail + 1)); echo "  FAIL $1"; printf '%s\n' "$2" | head -5 | sed 's/^/    /'; fi
}

check "casefold: every changed code point and a sample of unchanged ones" \
  "$(jq -c -L "$LIB" 'include "staging-format"; select((.in | sf_casefold) != .out) | {in, out, got: (.in | sf_casefold)}' "$FIX/casefold.jsonl")"
check "norm: casefolded letter and digit runs joined by one space" \
  "$(jq -c -L "$LIB" 'include "staging-format"; select((.in | sf_norm) != .out) | {in, out, got: (.in | sf_norm)}' "$FIX/norm.jsonl")"
check "render: every candidate shape renders the same block (null for a titleless one)" \
  "$(jq -c -L "$LIB" 'include "staging-format"; select((.in | sf_render) != .out) | {in, out, got: (.in | sf_render)}' "$FIX/render.jsonl")"
check "keys: board rows and staging headings give the same dedup keys" \
  "$(jq -c -L "$LIB" 'include "staging-format";
     (if .kind == "board" then .text | sf_board_keys else .text | sf_staging_keys end | unique) as $got
     | select($got != .keys) | {kind, text, keys, got: $got}' "$FIX/keys.jsonl")"

# shlex: bash side, one case at a time
source "$LIB/shlex-split.sh"
bad=""
while IFS= read -r line; do
  s=$(jq -j '.in, "x"' <<<"$line"); s=${s%x}; want=$(jq -c '.out' <<<"$line")
  if shlex_split "$s"; then
    if [ "${#SHLEX_ARGV[@]}" -eq 0 ]; then got='[]'; else got=$(printf '%s\0' "${SHLEX_ARGV[@]}" | jq -Rs -c 'split("\u0000")[:-1]'); fi
  else got=null; fi
  [ "$got" = "$want" ] || bad="$bad$(printf 'in=%s want=%s got=%s' "$s" "$want" "$got")"$'\n'
done < "$FIX/shlex.jsonl"
check "shlex: argv split, unterminated quote and trailing backslash refused" "${bad%$'\n'}"

echo "staging-format-jq: $pass passed, $fail failed"
[ "$fail" -eq 0 ]
